document.querySelector('#eraseData')?.addEventListener('click',()=>{const en=document.documentElement.lang==='en';if(!confirm(en?'Clear your saved cards from this browser? Export a backup first if you want to keep them.':'Je bewaarde kaarten uit deze browser wissen? Exporteer eerst een back-up als je die wilt behouden.'))return;const status=document.querySelector('#eraseStatus');try{localStorage.removeItem('kaartkompas-saved-v2');localStorage.removeItem('kaartkompas-saved');status.textContent=en?'Your local card collection has been cleared. Close other open Bindtopia tabs so an older tab does not save it again. Separate backups and photos are not affected.':'De lokale kaartverzameling is gewist. Sluit andere open Bindtopia-tabbladen om te voorkomen dat een oudere tab de verzameling opnieuw opslaat. Losse back-ups en foto’s blijven bestaan.'}catch{status.textContent=en?'Clearing failed. Remove the site data in your browser settings.':'Wissen lukte niet. Verwijder de sitegegevens via de instellingen van je browser.'}});
